"""Ops Hub IaC Generator — OHC Workflow Step 3.

Generates Terraform, Ansible, and validation artifacts for ops hub infrastructure.
Outputs the canonical JSON contract to stdout.
"""
import argparse
import json
import sys
import uuid
from datetime import datetime, timezone
from pathlib import Path

_ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(_ROOT))

_CANVAS = "ohc"
_ARTIFACTS_DIR = _ROOT / "data" / "studio_artifacts" / _CANVAS

# ── Terraform ─────────────────────────────────────────────────────────────────

_TF_MAIN = '''\
# Ops Hub Infrastructure — Generated by ICDEV™ OHC Workflow
# Generated: {ts}
# DO NOT EDIT — regenerate via OHC Workflow
# CUI // SP-CTI

terraform {{
  required_providers {{
    aws = {{
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }}
  }}
  required_version = ">= 1.6.0"
}}

locals {{
  common_tags = {{
    ManagedBy      = "icdev-ohc"
    Canvas         = "ohc"
    Environment    = var.environment
    Classification = "CUI"
  }}
}}

data "aws_caller_identity" "current" {{}}

# ── IAM — Lambda Execution Role ───────────────────────────────────────────────
resource "aws_iam_role" "ops_lambda" {{
  name = "${{var.environment}}-ohc-ops-lambda-role"
  assume_role_policy = jsonencode({{
    Version = "2012-10-17"
    Statement = [{{
      Effect    = "Allow"
      Principal = {{ Service = "lambda.amazonaws.com" }}
      Action    = "sts:AssumeRole"
    }}]
  }})
  tags = local.common_tags
}}

resource "aws_iam_role_policy" "ops_lambda_policy" {{
  name = "ohc-ops-policy"
  role = aws_iam_role.ops_lambda.id
  policy = jsonencode({{
    Version = "2012-10-17"
    Statement = [
      {{
        Effect   = "Allow"
        Action   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = "arn:aws:logs:*:*:log-group:/ohc/*"
      }},
      {{
        Effect   = "Allow"
        Action   = ["ssm:SendCommand", "ssm:GetCommandInvocation", "ssm:ListCommandInvocations"]
        Resource = "*"
      }},
      {{
        Effect   = "Allow"
        Action   = ["cloudwatch:PutMetricData", "cloudwatch:GetMetricData"]
        Resource = "*"
      }},
      {{
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject"]
        Resource = ["${{aws_s3_bucket.runbook_artifacts.arn}}", "${{aws_s3_bucket.runbook_artifacts.arn}}/*"]
      }}
    ]
  }})
}}

# ── SSM Document — Remediation: Restart Service ───────────────────────────────
resource "aws_ssm_document" "restart_service" {{
  name            = "${{var.environment}}-ohc-restart-service"
  document_type   = "Command"
  document_format = "YAML"

  content = <<-DOC
    schemaVersion: "2.2"
    description: "OHC automated remediation: restart service"
    parameters:
      ServiceName:
        type: String
        description: "Name of the service to restart"
        default: "${{var.service_name}}"
    mainSteps:
      - action: aws:runShellScript
        name: RestartService
        inputs:
          runCommand:
            - systemctl restart {{ ServiceName }}
            - systemctl status {{ ServiceName }}
    DOC

  tags = local.common_tags
}}

# ── SSM Document — Remediation: Scale Up ──────────────────────────────────────
resource "aws_ssm_document" "scale_up" {{
  name            = "${{var.environment}}-ohc-scale-up"
  document_type   = "Command"
  document_format = "YAML"

  content = <<-DOC
    schemaVersion: "2.2"
    description: "OHC automated remediation: scale up ECS service"
    parameters:
      ClusterName:
        type: String
        description: "ECS cluster name"
      ServiceName:
        type: String
        description: "ECS service name"
        default: "${{var.service_name}}"
      DesiredCount:
        type: String
        description: "Desired task count"
        default: "4"
    mainSteps:
      - action: aws:runShellScript
        name: ScaleUpService
        inputs:
          runCommand:
            - aws ecs update-service --cluster {{ ClusterName }} --service {{ ServiceName }} --desired-count {{ DesiredCount }}
    DOC

  tags = local.common_tags
}}

# ── Lambda — Ops Automation Health Check ─────────────────────────────────────
resource "aws_lambda_function" "ops_health_check" {{
  function_name = "${{var.environment}}-ohc-${{var.service_name}}-health-check"
  role          = aws_iam_role.ops_lambda.arn
  handler       = "health_check.handler"
  runtime       = "python3.12"
  timeout       = 60
  memory_size   = 256

  environment {{
    variables = {{
      SERVICE_NAME    = var.service_name
      ENVIRONMENT     = var.environment
      SSM_DOC_RESTART = aws_ssm_document.restart_service.name
      SNS_TOPIC_ARN   = aws_sns_topic.ops_notifications.arn
    }}
  }}

  filename = "${{path.module}}/lambda/${{var.service_name}}-health-check.zip"

  tags = local.common_tags
}}

# ── CloudWatch — Service Health Alarm ─────────────────────────────────────────
resource "aws_cloudwatch_metric_alarm" "service_health" {{
  alarm_name          = "${{var.environment}}-ohc-${{var.service_name}}-health"
  comparison_operator = "LessThanThreshold"
  evaluation_periods  = 2
  metric_name         = "HealthyHostCount"
  namespace           = "AWS/ApplicationELB"
  period              = 60
  statistic           = "Average"
  threshold           = 1
  alarm_description   = "Service ${{var.service_name}} has no healthy hosts"
  alarm_actions       = [aws_sns_topic.ops_notifications.arn]
  ok_actions          = [aws_sns_topic.ops_notifications.arn]
  tags                = local.common_tags
}}

# ── CloudWatch Event Rule — Scheduled Health Check (every 5 min) ──────────────
resource "aws_cloudwatch_event_rule" "health_check_schedule" {{
  name                = "${{var.environment}}-ohc-health-check"
  description         = "Trigger OHC health check every 5 minutes"
  schedule_expression = "rate(5 minutes)"
  tags                = local.common_tags
}}

# ── CloudWatch Event Target — Lambda Trigger ──────────────────────────────────
resource "aws_cloudwatch_event_target" "health_check_lambda" {{
  rule      = aws_cloudwatch_event_rule.health_check_schedule.name
  target_id = "OHCHealthCheckLambda"
  arn       = aws_lambda_function.ops_health_check.arn
}}

resource "aws_lambda_permission" "allow_cloudwatch" {{
  statement_id  = "AllowExecutionFromCloudWatch"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.ops_health_check.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.health_check_schedule.arn
}}

# ── SNS — Ops Notifications ───────────────────────────────────────────────────
resource "aws_sns_topic" "ops_notifications" {{
  name = "${{var.environment}}-ohc-ops-notifications"
  tags = local.common_tags
}}

resource "aws_sns_topic_subscription" "ops_email" {{
  topic_arn = aws_sns_topic.ops_notifications.arn
  protocol  = "email"
  endpoint  = var.ops_email
}}

# ── S3 — Runbook Artifacts ────────────────────────────────────────────────────
resource "aws_s3_bucket" "runbook_artifacts" {{
  bucket = "${{var.environment}}-ohc-runbook-artifacts-${{data.aws_caller_identity.current.account_id}}"
  tags   = local.common_tags
}}

# ── SSM — Ops Hub Config ──────────────────────────────────────────────────────
resource "aws_ssm_parameter" "ops_hub_config" {{
  name        = "/ohc/${{var.environment}}/config"
  type        = "String"
  value       = jsonencode({{
    service_name       = var.service_name
    ops_email          = var.ops_email
    health_check_rate  = "rate(5 minutes)"
    auto_remediation   = true
  }})
  description = "OHC ops hub configuration"
  tags        = local.common_tags
}}
'''

