_VALIDATION_SCRIPT = '''\
#!/usr/bin/env python3
"""OHC Ops Hub Infrastructure Validation Script — Generated by ICDEV™
Generated: {ts}

Run after `terraform apply` to verify all resources are provisioned.
Usage:
  pip install boto3
  python validate_{uid}.py --region us-gov-west-1 [--profile <aws-profile>]
"""
import argparse
import sys
import boto3


def check(label, ok, detail=""):
    status = "PASS" if ok else "FAIL"
    msg = "  [" + status + "] " + str(label)
    if detail:
        msg += " -- " + str(detail)
    print(msg)
    return ok


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--region", default="us-gov-west-1")
    parser.add_argument("--profile", default=None)
    parser.add_argument("--service-name", default="icdev-service")
    parser.add_argument("--env", default="ops")
    args = parser.parse_args()

    session = boto3.Session(region_name=args.region, profile_name=args.profile)
    passed = failed = 0
    svc = args.service_name
    env = args.env
    print("\\n=== OHC Ops Hub Infrastructure Validation ===\\n")

    # SSM documents
    try:
        ssm = session.client("ssm")
        docs = ssm.list_documents(
            Filters=[{{"Key": "Name", "Values": [f"{{env}}-ohc-restart-service", f"{{env}}-ohc-scale-up"]}}]
        )["DocumentIdentifiers"]
        ok = check("SSM remediation documents", len(docs) >= 2, f"{{len(docs)}} found")
    except Exception as e:
        ok = check("SSM remediation documents", False, str(e))
    passed += ok; failed += not ok

    # Lambda health check
    try:
        lam = session.client("lambda")
        fn = lam.get_function(FunctionName=f"{{env}}-ohc-{{svc}}-health-check")
        state = fn["Configuration"]["State"]
        ok = check("Lambda ops-health-check", state == "Active", state)
    except Exception as e:
        ok = check("Lambda ops-health-check", False, str(e))
    passed += ok; failed += not ok

    # CloudWatch alarm
    try:
        cw = session.client("cloudwatch")
        alarms = cw.describe_alarms(AlarmNames=[f"{{env}}-ohc-{{svc}}-health"])["MetricAlarms"]
        ok = check("CloudWatch service-health alarm", bool(alarms))
    except Exception as e:
        ok = check("CloudWatch service-health alarm", False, str(e))
    passed += ok; failed += not ok

    # SNS topic
    try:
        sns = session.client("sns")
        topics = sns.list_topics()["Topics"]
        found = any(f"{{env}}-ohc-ops-notifications" in t["TopicArn"] for t in topics)
        ok = check("SNS ops-notifications topic", found)
    except Exception as e:
        ok = check("SNS ops-notifications topic", False, str(e))
    passed += ok; failed += not ok

    # S3 runbook artifacts
    try:
        s3 = session.client("s3")
        sts = session.client("sts")
        account_id = sts.get_caller_identity()["Account"]
        bucket = f"{{env}}-ohc-runbook-artifacts-{{account_id}}"
        s3.head_bucket(Bucket=bucket)
        ok = check("S3 runbook-artifacts bucket", True, bucket)
    except Exception as e:
        ok = check("S3 runbook-artifacts bucket", False, str(e))
    passed += ok; failed += not ok

    # SSM parameter
    try:
        ssm = session.client("ssm")
        ssm.get_parameter(Name=f"/ohc/{{env}}/config")
        ok = check("SSM ops-hub config parameter", True)
    except Exception as e:
        ok = check("SSM ops-hub config parameter", False, str(e))
    passed += ok; failed += not ok

    print("\\n=== Result: " + str(passed) + " passed, " + str(failed) + " failed ===\\n")
    sys.exit(0 if failed == 0 else 1)


if __name__ == "__main__":
    main()
'''

_IAC_REPORT_MD = '''\
# OHC IaC Generation Report
**Generated:** {ts}
**Canvas:** Ops Hub Canvas (OHC)
**Approval Role:** ops_director
**Classification:** CUI // SP-CTI

## Artifacts Generated

| Artifact | Type | Purpose |
|----------|------|---------|
| `main_{uid}.tf` | Terraform | AWS ops hub infrastructure |
| `variables.tf` | Terraform | Variable declarations |
| `ansible_playbook_{uid}.yml` | Ansible | Ops agent deployment |
| `validate_{uid}.py` | Python | Post-deploy boto3 validation |

## Resources Provisioned

- **aws_ssm_document** (restart-service) — Automated service restart runbook
- **aws_ssm_document** (scale-up) — Automated ECS scale-up runbook
- **aws_lambda_function** — Ops automation health check (every 5 min)
- **aws_cloudwatch_metric_alarm** — Service health alarm
- **aws_cloudwatch_event_rule** — Scheduled health check (rate: 5 min)
- **aws_cloudwatch_event_target** — Lambda trigger for health checks
- **aws_sns_topic** — Ops team notifications
- **aws_sns_topic_subscription** — Email subscription for ops team
- **aws_s3_bucket** — Runbook artifacts storage
- **aws_ssm_parameter** — Ops hub configuration

## Apply Instructions

```bash
cd data/studio_artifacts/ohc/terraform
cp terraform.tfvars.example terraform.tfvars
# Edit: set vpc_id, private_subnet_ids, ops_email, service_name
terraform init && terraform plan -var-file=terraform.tfvars
terraform apply -var-file=terraform.tfvars
python ../validate_{uid}.py --region us-gov-west-1
```

## Approval Gate

**Required approver:** `ops_director`
Ops Director sign-off required before enabling auto-remediation in production.
'''


def generate_iac(project_id: str, run_id: str) -> dict:
    _ARTIFACTS_DIR.mkdir(parents=True, exist_ok=True)
    tf_dir = _ARTIFACTS_DIR / "terraform"
    tf_dir.mkdir(parents=True, exist_ok=True)

    uid = uuid.uuid4().hex[:8]
    ts = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

    main_tf = tf_dir / f"main_{uid}.tf"
    vars_tf = tf_dir / "variables.tf"
    ansible_pb = _ARTIFACTS_DIR / f"ansible_playbook_{uid}.yml"
    validate_py = _ARTIFACTS_DIR / f"validate_{uid}.py"
    report_md = _ARTIFACTS_DIR / f"iac_report_{uid}.md"

    main_tf.write_text(_TF_MAIN.format(ts=ts), encoding="utf-8", newline="")
    vars_tf.write_text(_TF_VARIABLES, encoding="utf-8", newline="")
    ansible_pb.write_text(_ANSIBLE_PLAYBOOK.format(ts=ts), encoding="utf-8", newline="")
    validate_py.write_text(_VALIDATION_SCRIPT.format(ts=ts, uid=uid), encoding="utf-8", newline="")
    report_md.write_text(_IAC_REPORT_MD.format(ts=ts, uid=uid), encoding="utf-8", newline="")

    return {
        "uid": uid,
        "main_tf": main_tf.relative_to(_ROOT).as_posix(),
        "vars_tf": vars_tf.relative_to(_ROOT).as_posix(),
        "ansible_pb": ansible_pb.relative_to(_ROOT).as_posix(),
        "validate_py": validate_py.relative_to(_ROOT).as_posix(),
        "report_md": report_md.relative_to(_ROOT).as_posix(),
    }


def main():
    parser = argparse.ArgumentParser(description="OHC IaC Generator — Step 3")
    parser.add_argument("--project-id", default="default")
    parser.add_argument("--run-id", default="")
    parser.add_argument("--canvas", default=_CANVAS)
    parser.add_argument("--json", action="store_true")
    args = parser.parse_args()

    try:
        result = generate_iac(args.project_id, args.run_id)

        output = {
            "gate": "PASS",
            "canvas": _CANVAS,
            "artifacts": [
                {"name": "Terraform Main", "path": result["main_tf"], "type": "tf"},
                {"name": "Terraform Variables", "path": result["vars_tf"], "type": "tf"},
                {"name": "Ansible Playbook", "path": result["ansible_pb"], "type": "yml"},
                {"name": "Validation Script", "path": result["validate_py"], "type": "py"},
                {"name": "IaC Generation Report", "path": result["report_md"], "type": "md"},
            ],
        }
        print(json.dumps(output))
        sys.exit(0)
    except Exception as exc:
        print(json.dumps({"gate": "FAIL", "canvas": _CANVAS, "error": str(exc), "artifacts": []}))
        sys.exit(1)


if __name__ == "__main__":
    main()
